package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.*;
import java.util.*;
final class AutomationPackagesBrowserAcceptance {
 static void click(Page page,String name){ServiceOutagesBrowserAcceptance.click(page,name);}
 static void run(BrowserTest h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h.store,h.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   String flow,action,alias="package-browser-"+id().substring(0,8);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);var config=EventWorkflowsAcceptance.config(0,"created","1",List.of(EventWorkflowsAcceptance.note()));config.put("active",false);object(config.get("definition")).put("name","Portable browser workflow");flow=object(EventWorkflows.save(db,"",config).get("flow")).get("flow_id").toString();var spec=ConnectorActionsAcceptance.spec(endpoint.provider.alias,0,"POST");spec.put("active",false);action=ConnectorActions.save(db,"",spec).get("action_id").toString();Connectors.save(h.store,db,actor,map("alias",alias,"origin",endpoint.provider.origin(),"token","browser-package-token"));db.connection.commit();}
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/configuration");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Automation packages").setExact(true)).press("Enter");page.getByLabel("Package name",new Page.GetByLabelOptions().setExact(true)).fill("Browser release <script>");page.getByLabel("Version label").fill("1.0");page.getByLabel("Workflow IDs (JSON list)").fill(JSON.writeValueAsString(List.of(flow)));page.getByLabel("Connector action IDs (JSON list)").fill(JSON.writeValueAsString(List.of(action)));var download=page.waitForDownload(()->click(page,"Download automation package"));Path file=Path.of("target/browser-automation-package.json");download.saveAs(file);var doc=object(JSON.readValue(Files.readString(file),Object.class));assertFalse(Files.readString(file).contains(endpoint.provider.origin()));assertFalse(Files.readString(file).contains("browser-package-token"));page.getByLabel("Automation package JSON").fill(JSON.writeValueAsString(doc));page.getByLabel("Destination bindings JSON").fill(JSON.writeValueAsString(map("groups",map(),"staff",map(),"aliases",map(endpoint.provider.alias,alias))));click(page,"Review destination installation");assertThat(page.locator("main")).containsText("Review inactive copies");assertThat(page.locator("main")).containsText(endpoint.provider.origin());assertThat(page.locator("main script")).hasCount(0);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/automation-package-review-light.png")).setFullPage(true));click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/automation-package-review-dark.png")).setFullPage(true));page.getByLabel("Install these exact inactive automation copies").check();click(page,"Install reviewed package");assertThat(page.locator("main")).containsText("Retained installation receipt");assertThat(page.locator("main")).not().containsText("No automation packages installed.");page.locator("a[href='/admin/automation-packages/"+doc.get("package_id")+"']").press("Enter");assertEquals(0,endpoint.calls.get());ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/automation-package-receipt-dark.png")).setFullPage(true));var retained=page.waitForDownload(()->page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Download retained package")).press("Enter"));retained.saveAs(file);assertEquals(doc,JSON.readValue(Files.readString(file),Object.class));var installed=page.locator("a[href^='/admin/event-flows/']");assertThat(installed).hasCount(1);installed.press("Enter");assertThat(page.getByLabel("Flow availability")).hasValue("false");page.getByLabel("Flow availability").selectOption("true");click(page,"Save event workflow");assertThat(page.getByLabel("Flow availability")).hasValue("true");assertEquals(0,endpoint.calls.get());
  }
 }
}
